      p_source         => 
'SELECT
    l.loan_id,
    m.member_id,
    m.name AS member_name,
    b.book_id,
    b.title AS book_title,
    bc.barcode,
    l.loan_date,
    l.due_date,
    l.return_date,
    l.status AS loan_status,
    NVL(f.amount, 0) AS fine_amount,
    NVL(f.payment_status, ''NO_FINE'') AS payment_status

FROM loans l

JOIN members m
    ON l.member_id = m.member_id

JOIN book_copies bc
    ON l.copy_id = bc.copy_id

JOIN books b
    ON bc.book_id = b.book_id

LEFT JOIN fines f
    ON l.loan_id = f.loan_id

ORDER BY l.loan_date DESC
');

