      p_comments       => NULL,
      p_source         => 
'
SELECT
    l.loan_id,
    m.member_id,
    m.name AS member_name,
    b.title AS book_title,
    bc.copy_id,
    bc.barcode,
    l.loan_date,
    l.due_date,
    l.status AS loan_status,

    CASE
        WHEN TRUNC(SYSDATE) > TRUNC(l.due_date)
        THEN TRUNC(SYSDATE) - TRUNC(l.due_date)
        ELSE 0
    END AS late_days,

    CASE
        WHEN TRUNC(SYSDATE) > TRUNC(l.due_date)
        THEN (TRUNC(SYSDATE) - TRUNC(l.due_date)) * 2000
        ELSE 0
    END AS estimated_fine

FROM loans l

JOIN members m
    ON l.member_id = m.member_id

JOIN book_copies bc
    ON l.copy_id = bc.copy_id

JOIN books b
    ON bc.book_id = b.book_id

WHERE l.status IN (''BORROWED'', ''OVERDUE'')

ORDER BY l.due_date ASC
');

