      p_source_type    => 'plsql/block',
      p_mimes_allowed  => NULL,
      p_comments       => NULL,
      p_source         => 
'
DECLARE
    l_body     JSON_OBJECT_T;
    l_loan_id  NUMBER;
    l_due_date DATE;
BEGIN
    -- Membaca JSON dari React
    l_body := JSON_OBJECT_T.parse(:body_text);

    -- Mengambil tanggal jatuh tempo
    l_due_date := TO_DATE(
        l_body.get_string(''due_date''),
        ''YYYY-MM-DD''
    );

    -- Memanggil Procedure peminjaman
    sp_borrow_book(
        p_member_id => l_body.get_number(''member_id''),
        p_staff_id  => l_body.get_number(''staff_id''),
        p_copy_id   => l_body.get_number(''copy_id''),
        p_due_date  => l_due_date,
        p_loan_id   => l_loan_id
    );

    COMMIT;

    -- Mengirim respons JSON
    OWA_UTIL.mime_header(''application/json'', TRUE);

    HTP.p(
        ''{"message":"Peminjaman berhasil",''
        || ''"loan_id":'' || l_loan_id || ''}''
    );

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
');

